translations_part1 = {
    "The Exposure Triangle in Astrophotography": "<p><strong>הגדרה:</strong> משולש החשיפה בצילום אסטרונומי מתאים את עקרונות הצילום הרגיל לאתגרים הקיצוניים של צילום עצמים שמימיים עמומים. שלושת הצלעות הן זמן חשיפה, רווח (Gain/ISO), ויחס מוקד (Focal Ratio). המטרה היא למקסם את SNR תוך מזעור הרעש מהחיישן ומזיהום האור.</p><p><strong>דוגמה:</strong> בצילום ערפיליות בשמיים עמוקים, תגדיל את זמן החשיפה ותוריד את ה-Gain כדי לאסוף יותר פוטונים עם פחות רעש קריאה, בניגוד לצילום ביום.</p>",
    "Calibration Frames (Darks, Flats, Biases)": "<p><strong>הגדרה:</strong> פריימי כיול הם תמונות מיוחדות להסרת פגמים קבועים מתמונות המדע. פריים חשוך מסיר רעש תרמי, פריים שטוח מתקן אי-אחידות תאורה ווינייטינג, ופריים הטיה מסיר את ההיסט הבסיסי של החיישן.</p><p><strong>דוגמה:</strong> בלי פריים שטוח, תמונת הגלקסיה שלך תראה פינות כהות. עם פריים שטוח, השדה כולו יהיה אחיד.</p>",
    "Backfocus": "<p><strong>הגדרה:</strong> מרחק הבקפוקוס הוא המרחק המדויק בין האלמנט האופטי האחרון של הטלסקופ לבין מישור החיישן של המצלמה. כל טלסקופ דורש מרחק ספציפי זה לפוקוס מדויק ושדה תמונה שטוח.</p><p><strong>דוגמה:</strong> אם ה-Backfocus של הרפרקטור שלך הוא 55 מ\"מ, עליך לכוון את כל הרכיבים כך שהמרחק הכולל יהיה בדיוק 55 מ\"מ.</p>",
    "Equatorial (EQ) vs Alt-Azimuth (Alt-Az) Mounts": "<p><strong>הגדרה:</strong> חצובה משוונית (EQ) מיושרת עם ציר הסיבוב של כדור הארץ ומאפשרת מעקב בציר אחד. חצובת Alt-Az נעה בציר אנכי ואופקי ופשוטה יותר אך דורשת סיבוב שדה לחשיפות ארוכות.</p><p><strong>דוגמה:</strong> לצילום עצמים בשמיים עמוקים תשתמש בחצובת EQ כמו Losmandy G11, ואילו לצפייה חזותית חצובת Alt-Az מספיקה.</p>",
    "Monochrome vs Color (OSC) Cameras": "<p><strong>הגדרה:</strong> מצלמה מונוכרומטית מודדת רק עוצמת אור ונותנת גמישות בבחירת פילטרים. מצלמת OSC (One-Shot Color) כוללת מטריצת בייר על החיישן ומאפשרת צילום צבע בחשיפה אחת.</p><p><strong>דוגמה:</strong> עם מצלמה מונוכרומטית תצלם בנפרד פילטרי Ha, OIII ו-SII ותשלב אותם; עם OSC תקבל צבע מיד אך עם רגישות נמוכה יותר בפס צר.</p>",
    "Apochromatic Refractor (APO)": "<p><strong>הגדרה:</strong> רפרקטור אפוכרומטי משתמש בזכוכית מיוחדת (כמו ED או FPL-53) להתכנסות שלוש אורכי גל לאותה נקודת מוקד, וכך מבטל את הסטייה הכרומטית הנפוצה ברפרקטורים רגילים.</p><p><strong>דוגמה:</strong> רפרקטור APO כמו FLT132 יראה כוכבים חדים ולבנים, ללא הילה סגולה הנפוצה ברפרקטורים זולים.</p>",
    "Backfocal Distance (Backfocus)": "<p><strong>הגדרה:</strong> המרחק המדויק מנקודת ההתייחסות של הטלסקופ לפשש החיישן של המצלמה. שגיאה במרחק זה גורמת לכיפוף שדה ולכוכבים מטושטשים בפינות התמונה.</p><p><strong>דוגמה:</strong> רדוסר/פלטנר ייעודי לרפרקטור שלך מיועד לעבוד במרחק בקפוקוס של 55 מ\"מ - סטייה של 1 מ\"מ תגרום לכוכבים עגולים פחות בפינות.</p>",
    "Harmonic Drive Mount": "<p><strong>הגדרה:</strong> חצובה המשתמשת במנגנון הנעה הרמוני (Strain Wave Gear) במקום תולעת ומשפד רגילה, המציע דיוק גבוה, ריפיון מכני אפסי כמעט ומשקל קל.</p><p><strong>דוגמה:</strong> חצובות כמו Rainbow Astro RST-135 משתמשות ב-Harmonic Drive ומסוגלות לשאת עומס כבד יחסית למשקלן הנמוך, אידאלי לצילום בשטח.</p>",
    "Plate Solving": "<p><strong>הגדרה:</strong> תהליך אוטומטי שבו התוכנה מתאימה את הכוכבים בתמונה לקטלוג כוכבים ידוע, ומוצאת בדיוק לאן הטלסקופ מכוון בשמיים (קואורדינטות RA ו-DEC).</p><p><strong>דוגמה:</strong> לאחר Plate Solve ב-N.I.N.A., הטלסקופ יכוון את עצמו לצמד הגלקסיות M81/M82 בדיוק של שניות קשת, גם אם ה-GoTo לא היה מדויק.</p>",
    "Off-Axis Guider (OAG)": "<p><strong>הגדרה:</strong> מכשיר המנתב חלק קטן מאור הטלסקופ הראשי לחיישן מצלמת הכוון דרך פריזמה קטנה, המאפשר כוון אוטומטי דרך אותה אופטיקה ממש בלי טלסקופ כוון נפרד.</p><p><strong>דוגמה:</strong> עם OAG נמנעת כיפוף מוט שנוצר כשטלסקופ הכוון וטלסקופ הצילום נעים בנפרד, וכך הכוון מדויק יותר בחשיפות ארוכות.</p>",
    "Quantum Efficiency (QE)": "<p><strong>הגדרה:</strong> אחוז הפוטונים הפוגעים בחיישן המצלמה שמומרים בפועל לאלקטרונים הניתנים למדידה. QE גבוה יותר פירושו חיישן יעיל יותר בלכידת אור.</p><p><strong>דוגמה:</strong> חיישן עם QE של 91% (כמו IMX455 ב-ASI2600) יאסוף כמעט פי שניים יותר אות ביחס לחיישן עם QE של 50% בזמן חשיפה זהה.</p>",
    "Signal-to-Noise Ratio (SNR)": "<p><strong>הגדרה:</strong> יחס האות לרעש (SNR) מודד את עוצמת האות הרצוי (אור מהעצם) ביחס לרמת הרעש הכללית. SNR גבוה יותר פירושו תמונה נקייה ועשירה יותר בפרטים.</p><p><strong>דוגמה:</strong> הגדלת זמן אינטגרציה פי 4 מכפילה את SNR פי 2. לכן ערימה של 4 שעות תיראה פי שניים נקייה מערימה של שעה אחת.</p>",
    "Dithering": "<p><strong>הגדרה:</strong> ניתור הוא הזזה קטנה ומכוונת של כוון הטלסקופ בין חשיפה לחשיפה. כאשר מערמים את הפריימים, הרעש הקבוע (hot pixels, FPN) מבוטל כי אינו נמצא באותו מיקום בכל פריים.</p><p><strong>דוגמה:</strong> הפעלת Dithering ב-N.I.N.A. בין כל חשיפה תסיר רצועות רעש מלח ופלפל שנשארות לאחר ערימה ללא ניתור.</p>",
    "Linear vs. Non-Linear": "<p><strong>הגדרה:</strong> תמונה לינארית היא נתון גולמי שבו ערכי הפיקסל פרופורציוניים ישירות לכמות הפוטונים שנאספו. לאחר מתיחה (Stretch) התמונה הופכת ללא-לינארית.</p><p><strong>דוגמה:</strong> ב-PixInsight תבצע כיול, ערימה וחיסור שיפוע (DBE) במצב לינארי לפני שתמתח את התמונה לצפייה.</p>",
    "Bayer Matrix (Debayering)": "<p><strong>הגדרה:</strong> מטריצת בייר היא רשת פילטרים צבעוניים (RGGB) הממוקמת על חיישן מצלמת OSC, כאשר כל פיקסל קולט רק צבע אחד. תהליך Debayering משחזר את המידע הצבעוני המלא לכל פיקסל.</p><p><strong>דוגמה:</strong> קובץ RAW ממצלמת ASI2600MC מכיל נתוני בייר גולמיים; לאחר Debayering בתוכנת ערימה כמו APP, כל פיקסל מקבל ערכי R, G ו-B מלאים.</p>",
    "Hydrogen-Alpha (H\u03b1)": "<p><strong>הגדרה:</strong> קו פליטה של מימן ניטרלי באורך גל 656.3 ננומטר (אדום עמוק). זהו קו הפליטה החזק ביותר בערפיליות פליטה, ופילטר Hα מבודד אותו מכל שאר האור.</p><p><strong>דוגמה:</strong> צילום ערפילית הרוזטה עם פילטר Hα של 3nm חושף את מבנה הגז בבהירות גם בירח מלא, כי הפילטר חוסם כמעט את כל זיהום האור.</p>",
    "Oxygen-III (OIII)": "<p><strong>הגדרה:</strong> קו פליטה של חמצן מיוּנן פעמיים באורך גל 500.7 ננומטר (ירוק-כחול). הוא נפוץ בערפיליות פלנטריות ובאזורים חמים מאוד של ערפיליות פליטה.</p><p><strong>דוגמה:</strong> ערפילית הרשת בקבוצת הברבור (Veil Nebula) זוהרת בעוצמה בפילטר OIII, ומגלה סיבי שוקוויב עדינים שלא נראים ב-Hα.</p>",
    "Hubble Palette (SHO)": "<p><strong>הגדרה:</strong> שיטת מיפוי צבע שבה SII ממופה לאדום, Hα לירוק ו-OIII לכחול. התוצאה היא תמונות בצבעים שקריים אך עשירות במידע מדעי, כמו תמונות המפורסמות של טלסקופ האבל.</p><p><strong>דוגמה:</strong> עמודי הבריאה המפורסמים של האבל צולמו בפלטת SHO - הצבע הירוק-צהוב הוא למעשה אות Hα חזק.</p>",
    "The Bortle Scale": "<p><strong>הגדרה:</strong> סולם מ-1 עד 9 המדרג את חשכת השמיים. Bortle 1 מייצג שמיים כהים לחלוטין ו-Bortle 9 מייצג מרכז עיר עם שמיים בהירים.</p><p><strong>דוגמה:</strong> בשמיים של Bortle 4 תוכל לצלם ערפיליות עמומות עם פחות שעות ערימה מאשר ב-Bortle 7, כי הרקע הכהה יותר נותן SNR טוב יותר.</p>",
    "Astronomical Seeing": "<p><strong>הגדרה:</strong> ראייה אסטרונומית מתארת את יציבות האטמוספרה - כמה מהר ובאיזה עוצמה זרמי אוויר מטשטשים את תמונת הכוכבים. ראייה טובה = כוכבים קטנים וחדים.</p><p><strong>דוגמה:</strong> בלילה עם ראייה של 2 ארקסק הכוכבים יהיו חדים, ואילו ב-5 ארקסק אפילו הטלסקופ הטוב ביותר לא יניב תוצאות חדות.</p>",
    "Bias Frame": "<p><strong>הגדרה:</strong> פריים הטיה הוא חשיפה קצרה ביותר (זמן חשיפה אפסי) עם מכסה העדשה סגור. הוא מודד את ההיסט הבסיסי שהחיישן מוסיף לכל פיקסל ללא קשר לאור או חום.</p><p><strong>דוגמה:</strong> גריעת Master Bias מפריימי המדע וכלי הכיול האחרים מבטיחה שהמתמטיקה של הכיול מדויקת ולא מוסיפה ערכים שקריים.</p>",
    "Dark Frame": "<p><strong>הגדרה:</strong> פריים חשוך הוא חשיפה באותו משך זמן, טמפרטורה ורווח כמו פריימי המדע, אך עם מכסה סגור. הוא קולט רעש תרמי, hot pixels ו-Amp Glow שניתן לגרוע מהתמונה.</p><p><strong>דוגמה:</strong> ערימה של 20 פריים חשוכים ל-Master Dark תסיר בצורה אמינה את כל הפיקסלים החמים הקבועים בתמונת הגלקסיה שלך.</p>",
    "Flat Frame": "<p><strong>הגדרה:</strong> פריים שטוח הוא תמונה של מקור אור אחיד שמגלה את אי-האחידות של שדה הראייה: וינייטינג, אבק על החיישן וחוסר אחידות בפילטרים.</p><p><strong>דוגמה:</strong> לאחר גריעת Master Flat מתמונת ערפילית, הפינות הכהות נעלמות ושדה התמונה כולו נראה אחיד ושטוח.</p>",
    "Dark-Flat Frame": "<p><strong>הגדרה:</strong> פריים Dark-Flat הוא פריים חשוך הצולם בזמן החשיפה הזהה לפריים השטוח. הוא מסיר את הרעש התרמי הייחודי של פריימי הפלאט.</p><p><strong>דוגמה:</strong> אם פריימי הפלאט שלך נמשכים 0.5 שניות, צלם Dark-Flat של 0.5 שניות עם מכסה סגור וגרע אותם מהפלאטים.</p>",
    "Master Frame": "<p><strong>הגדרה:</strong> Master Frame הוא תמונת כיול ממוצעת הנוצרת מערימת פריימי כיול רבים. היא מפחיתה את הרעש בפריים הכיול עצמו.</p><p><strong>דוגמה:</strong> Master Dark הנוצר מ-30 פריים חשוכים יהיה נקי הרבה יותר מפריים חשוך בודד, ויסיר hot pixels בצורה אמינה.</p>",
    "Sub-frame Weighting": "<p><strong>הגדרה:</strong> שקלול פריימים הוא תהליך שבו כל פריים מדע מקבל ציון איכות על בסיס FWHM, SNR וסטיית תקן. פריימים איכותיים יותר מקבלים משקל גבוה יותר בערימה.</p><p><strong>דוגמה:</strong> בלילה עם ראייה משתנה, פריים עם כוכבים חדים של 2 ארקסק יקבל משקל גבוה פי 3 מפריים עם כוכבים מטושטשים של 5 ארקסק.</p>",
    "Pixel Rejection (Sigma Clipping)": "<p><strong>הגדרה:</strong> שיטה סטטיסטית שמזהה ומסירה ערכי פיקסל חריגים (כוכבי לוויין, קוסמיק ריי, hot pixels) מהערימה על ידי השוואה לסטיית תקן של הממוצע.</p><p><strong>דוגמה:</strong> Sigma Clipping של 3σ יסיר את עקבות הלוויין מהערימה הסופית מבלי לפגוע באות הגלקסיה האמיתי.</p>",
    "Registration (Alignment)": "<p><strong>הגדרה:</strong> יישור תמונות הוא תהליך מציאת ותיקון ההזזות הקטנות (טרנסלציה, סיבוב) בין פריימים שנצלמו בלילות שונים, כך שכוכבים מסוימים נמצאים באותם פיקסלים בכל הפריימים.</p><p><strong>דוגמה:</strong> בכלי ערימה כמו APP, יישור בסיס כוכבים מאפשר לחבר נתוני לילות שונים ולהשיג ערימה עמוקה ללא כוכבים כפולים.</p>",
    "Drizzle (Bayer Drizzle)": "<p><strong>הגדרה:</strong> אלגוריתם Drizzle ממפה כל פיקסל קטן יותר על רשת פלט גדולה יותר, וכך מגדיל ברזולוציה את הנתונים בזמן הערימה תוך שמירה על מידע שנאסף על ידי כל חיישן.</p><p><strong>דוגמה:</strong> שימוש ב-Bayer Drizzle על נתוני OSC מכפיל את הרזולוציה האפקטיבית לפני פירוק הבייר ומפחית את אובדן הרזולוציה האופייני.</p>",
    "Deconvolution": "<p><strong>הגדרה:</strong> דה-קונבולוציה היא תהליך מתמטי שמנסה לבטל את הטשטוש שנגרם על ידי הטלסקופ, האטמוספרה ואופטיקה לא מושלמת, ולחלץ את פרטי הנושא האמיתיים.</p><p><strong>דוגמה:</strong> שימוש ב-BlurXTerminator על תמונת גלקסיית המערבולת יחדד את זרועות הספירלה ויחשוף פרטי אבק שלא נראו בתמונה המקורית.</p>",
    "Star Reduction (Morphological Transformation)": "<p><strong>הגדרה:</strong> טרנספורמציה מורפולוגית היא עיבוד שמכווץ את גודל הכוכבים בתמונה מבלי להשפיע על פרטי הנבולה, כך שהנבולה מנצחת ויזואלית על הכוכבים.</p><p><strong>דוגמה:</strong> לאחר Star Reduction ב-PixInsight, הכוכבים בתמונת ערפילית הטאדפול יהיו קטנים ועדינים, ותשומת הלב תעבור לאות הגז.</p>",
    "SCNR (Subtractive Chromatic Noise Reduction)": "<p><strong>הגדרה:</strong> SCNR הוא כלי שמסיר ערוץ צבע ספציפי (בדרך כלל ירוק) מהאזורים שבהם הוא שולט, ומסיר את הגוון הירקרק האופייני בתמונות OSC.</p><p><strong>דוגמה:</strong> הפעלת SCNR Green ב-PixInsight על תמונת ערפילית מסירה את הצבע הירוק הקנביוס ומשאירה אדום וכחול טבעיים.</p>",
    "Local Histogram Equalization (LHE)": "<p><strong>הגדרה:</strong> LHE היא טכניקת עיבוד שמשווה את ההיסטוגרמה באזורים מקומיים קטנים בתמונה, ומגביר ניגוד ופרטים באזורים ספציפיים מבלי להשפיע על כל התמונה.</p><p><strong>דוגמה:</strong> שימוש ב-LHE על ליבת גלקסיה יחשוף פרטים עדינים ומבנים פנימיים מבלי לשרוף (Clip) את הכוכבים הבהירים בסביבה.</p>",
    "PixelMath": "<p><strong>הגדרה:</strong> PixelMath הוא כלי ב-PixInsight המאפשר ביצוע פעולות מתמטיות ישירות על ערכי הפיקסלים בתמונה באמצעות נוסחאות וביטויים תכנותיים.</p><p><strong>דוגמה:</strong> בשיטת HOO (Hα לאדום, OIII לכחול וירוק), תשתמש בנוסחת PixelMath כדי לשלב שלושה ערוצי פס-צר לתמונה RGB.</p>",
    "Dynamic Background Extraction (DBE)": "<p><strong>הגדרה:</strong> DBE הוא כלי ב-PixInsight שממדל ומסיר שיפועי רקע לא-אחידים (gradient) מתמונה, הנגרמים מזיהום אור, Airglow או כיול לא מושלם.</p><p><strong>דוגמה:</strong> לאחר ערימת נתוני ערפילית עם שיפוע אורכי מאדות ירח, DBE יסיר את אי-האחידות וישאיר רקע שחור אחיד.</p>",
    "Right Ascension (RA)": "<p><strong>הגדרה:</strong> נסיקה ישרה (RA) היא הקואורדינטה האסטרונומית המקבילה לאורך גיאוגרפי, ומודדת את המיקום של עצם שמימי מזרחה מנקודת הורנל. מודדים אותה בשעות, דקות ושניות.</p><p><strong>דוגמה:</strong> גלקסיית אנדרומדה (M31) נמצאת ב-RA 00h 42m - כשהטלסקופ מכוון לשם, ציר ה-RA של החצובה מסתובב לאט כדי לעקוב.</p>",
    "Declination (DEC)": "<p><strong>הגדרה:</strong> נטייה (DEC) היא הקואורדינטה האסטרונומית המקבילה לרוחב גיאוגרפי, ומודדת זווית צפון-דרום מהמשוון השמימי. מקסימום +90 מעלות (קוטב צפון שמימי) ו-90- מעלות (קוטב דרום שמימי).</p><p><strong>דוגמה:</strong> ערפילית אוריון (M42) נמצאת ב-DEC של -5.4 מעלות - מתחת מעט למשוון השמימי, ולכן נראית מכל רחבי העולם.</p>",
    "Meridian": "<p><strong>הגדרה:</strong> המרידיאן הוא הקשת השמימית הדמיונית העוברת מנקודת הצפון דרך הזניט ועד נקודת הדרום. עצמים שמימיים מגיעים לשיאם כשהם עוברים את המרידיאן.</p><p><strong>דוגמה:</strong> הטלסקופ צריך לבצע Meridian Flip כשהעצם עובר מצד מזרח למערב של המרידיאן, אחרת צינור הטלסקופ יפגע בחצובה.</p>",
    "Meridian Flip": "<p><strong>הגדרה:</strong> היפוך מרידיאן הוא תהליך שבו החצובה המשוונית מסיבה את הטלסקופ 180 מעלות לכיוון ההפוך כדי להמשיך לעקוב אחר עצם שעבר את המרידיאן ולמנוע פגיעה פיזית בציוד.</p><p><strong>דוגמה:</strong> ב-N.I.N.A. תוכל לתכנת את ה-Meridian Flip להתרחש אוטומטית 5 דקות לאחר המעבר, תוך שהתוכנה מבצעת Plate Solve חדש ליישור מחדש.</p>",
    "Celestial Equator": "<p><strong>הגדרה:</strong> המשוון השמימי הוא ההשלכה של קו המשוון של כדור הארץ על כיפת השמיים. הוא מחלק את השמיים לחצי כדור צפוני ודרומי.</p><p><strong>דוגמה:</strong> עצמים הנמצאים קרוב למשוון השמימי (DEC כ-0 מעלות) גלויים ממרבית מקומות על פני הארץ, ובישראל הם עולים לגובה בינוני.</p>",
    "Emission Nebula": "<p><strong>הגדרה:</strong> ערפילית פליטה היא ענן גז (בעיקר מימן) המואר על ידי קרינה אולטרה-סגולה מכוכבים חמים בסביבה. הקרינה מייננת את הגז שפולט אור עצמי בצבעים אופייניים.</p><p><strong>דוגמה:</strong> ערפילית אוריון (M42) היא ערפילית פליטה ענקית. הגוון האדום שלה נובע מקו Hα של מימן מיוּנן בטמפרטורות גבוהות מאוד.</p>",
    "Reflection Nebula": "<p><strong>הגדרה:</strong> ערפילית השתקפות היא ענן אבק וגז שאינו חם מספיק לפלוט אור עצמי, אלא מחזיר (מפזר) את אור הכוכבים שבסביבתו. לרוב מופיעה בגוון כחלחל.</p><p><strong>דוגמה:</strong> ערפילית הפלאיאדות (M45) מוקפת בערפילית השתקפות כחולה. האבק מפזר את אור הכוכבים הכחולים-לבנים ויוצר את הערפל המפורסם.</p>",
    "Dark Nebula": "<p><strong>הגדרה:</strong> ערפילית חשוכה היא ענן אבק צפוף החוסם את אור הכוכבים והערפיליות שמאחוריו. היא נראית כחור כהה על רקע שדה כוכבים צפוף.</p><p><strong>דוגמה:</strong> ראש הסוס (Horsehead Nebula) הוא ערפילית חשוכה הבולטת כסיבת סוס על רקע ערפילית פליטה אדומה. צילומה נעשה בדרך כלל עם פילטר Hα.</p>",
    "Planetary Nebula": "<p><strong>הגדרה:</strong> ערפילית פלנטרית היא מעטפת גז מתפשטת הנפלטת על ידי כוכב בסיום חייו. הגז הקורן מוסק על ידי ליבת הכוכב הלבנה (White Dwarf) שנותרה.</p><p><strong>דוגמה:</strong> ערפילית הטבעת (M57) היא ערפילית פלנטרית קלאסית. בחשיפות ארוכות עם OIII תגלה את מבנה הבועה השלמה סביב הכוכב הלבן.</p>",
    "Supernova Remnant (SNR)": "<p><strong>הגדרה:</strong> שארית סופרנובה היא השאר שנותר לאחר פיצוץ כוכב מסיבי. גלי הלחץ העצומים מייננים את הגז הסובב ויוצרים מבנים עדינים ומורכבים הגלויים בעיקר ב-Hα ו-OIII.</p><p><strong>דוגמה:</strong> ערפילית הרשת (Veil Nebula) בקבוצת הברבור היא שארית סופרנובה ענקית. הסיבים העדינים שמצלמים הם גלי הלחץ של כוכב שהתפוצץ לפני אלפי שנים.</p>",
    "Airmass": "<p><strong>הגדרה:</strong> מסת אוויר מודדת את כמות האטמוספרה שהאור חייב לחדור כדי להגיע לטלסקופ. ערך 1.0 בזניט ועולה ככל שמסתכלים לאופק.</p><p><strong>דוגמה:</strong> צילום גלקסיה במסת אוויר 3.0 (נמוך על האופק) נותן תמונות מטושטשות וצהובות, כי האור עובר פי שלוש יותר אוויר.</p>",
    "Atmospheric Dispersion": "<p><strong>הגדרה:</strong> פיזור אטמוספרי הוא אפקט הפריזמה של האטמוספרה המפצל את אור הכוכבים לספקטרום קטן (אדום למעלה, כחול למטה), בעיקר כשהעצמים נמוכים בשמיים.</p><p><strong>דוגמה:</strong> בצילום צדק ליד האופק תראה שוליים אדומים בצד אחד וכחולים בצד השני - זהו פיזור אטמוספרי, לא פגם בטלסקופ.</p>",
    "Extinction": "<p><strong>הגדרה:</strong> כיבוי אור (Extinction) הוא אובדן האור מגוף שמימי בעת מעברו דרך האטמוספרה, הנגרם מספיגה ופיזור על ידי מולקולות אוויר ואבק.</p><p><strong>דוגמה:</strong> כוכב נראה עמום הרבה יותר קרוב לאופק מאשר בזניט. לכן ממתינים שהמטרה תעלה גבוה לפני תחילת חשיפות ה-Luminance.</p>",
    "Integration Time (Total)": "<p><strong>הגדרה:</strong> זמן אינטגרציה כולל הוא סכום כל החשיפות הבודדות (subs) המשולבות לתמונה סופית. זמן ארוך יותר מוביל ישירות ל-SNR גבוה יותר.</p><p><strong>דוגמה:</strong> אם צלמת 60 פריימים של 300 שניות כל אחד, זמן האינטגרציה הכולל הוא 5 שעות. הכפלת הזמן משפרת את ה-SNR פי 1.4.</p>",
    "Opposition": "<p><strong>הגדרה:</strong> אופוזיציה היא הרגע שבו כוכב לכת כמו מאדים או צדק נמצא בצדו הנגדי של כדור הארץ ביחס לשמש. הכוכב מואר במלואו ונמצא בנקודת הקירבה הגדולה ביותר לכדור הארץ.</p><p><strong>דוגמה:</strong> במהלך אופוזיציה של מאדים הכוכב נראה גדול הרבה יותר בטלסקופ ומאפשר לצלם פרטי פני שטח עדינים.</p>",
    "Conjunction": "<p><strong>הגדרה:</strong> צימוד (Conjunction) הוא אירוע שבו שני עצמים שמימיים נראים קרובים מאוד זה לזה בשמיים מנקודת מבטנו מכדור הארץ.</p><p><strong>דוגמה:</strong> הצימוד הגדול של צדק ושבתאי בשנת 2020 אפשר לצלם את שני הכוכבים בשדה ראייה אחד בהגדלה גבוהה.</p>",
    "Transit": "<p><strong>הגדרה:</strong> מעבר (Transit) הוא אירוע שבו גוף שמימי קטן עובר מול גוף גדול יותר - למשל כוכב לכת מול פני השמש, או ירח מלאכותי מול גוף שמימי.</p><p><strong>דוגמה:</strong> צילום מעבר תחנת החלל הבינלאומית (ISS) על פני השמש דורש מהירויות תריס של פחות ממילישנייה ותזמון מדויק.</p>",
    "Ecliptic Plane": "<p><strong>הגדרה:</strong> מישור האקליפטיקה הוא המישור הדמיוני המוגדר על ידי מסלול כדור הארץ סביב השמש. רוב כוכבי הלכת נמצאים בתוך כמה מעלות ממישור זה.</p><p><strong>דוגמה:</strong> אם מחפשים את שבתאי, מסתכלים לאורך האקליפטיקה - לעולם לא תמצא כוכב לכת גדול ליד כוכב הצפון (פולאריס).</p>",
    "Chromatic Aberration (Color Fringing)": "<p><strong>הגדרה:</strong> סטייה כרומטית היא פגם אופטי שבו עדשה אינה מתכנסת את כל הצבעים לאותה נקודת מוקד, מה שגורם להילות סגולות או כחולות סביב כוכבים בהירים.</p><p><strong>דוגמה:</strong> רפרקטור Achromat תקציבי יראה שוליים סגולים בולטים על כוכב ורגה, ואילו APO תלת-גלי מבטל אפקט זה.</p>",
    "Coma": "<p><strong>הגדרה:</strong> קומה (Coma) היא סטייה אופטית הנפוצה בניוטוניאנים, שבה כוכבים בשוליים של שדה הראייה נראים כמו שביטים קטנים המצביעים לכיוון המרכז.</p><p><strong>דוגמה:</strong> ללא מתקן קומה (Coma Corrector), הכוכבים בפינות תמונת M31 ייראו מרוחים, גם אם המרכז חד לחלוטין.</p>",
    "Field Curvature": "<p><strong>הגדרה:</strong> עיקום שדה הוא תכונה טבעית של עדשות שבה מישור הפוקוס הוא למעשה עקומה. אם המרכז חד, הקצוות מטושטשים, ולהפך.</p><p><strong>דוגמה:</strong> לקבלת שדה שטוח עם חיישן גדול כמו ASI2600, יש להשתמש ב-Field Flattener שמייישר את מישור הפוקוס.</p>",
    "Spherical Aberration": "<p><strong>הגדרה:</strong> סטייה כדורית היא מצב שבו קרני אור הפוגעות בשוליים של מראה או עדשה מתכנסות בנקודה שונה מקרני המרכז, ויוצרות תמונה רכה וזוהרת.</p><p><strong>דוגמה:</strong> אם מראת הטלסקופ לא מלוטשת לפרבולה מושלמת, הכוכבים לעולם לא יהיו נקודות חדות אלא יהיה להם ערפל קל.</p>",
    "Astigmatism": "<p><strong>הגדרה:</strong> אסטיגמטיזם הוא פגם אופטי שבו הטלסקופ מתכנס את האור לקו ולא לנקודה, לרוב בגלל אופטיקה לחוצה (Pinched Optics) או רכיבים מוטים.</p><p><strong>דוגמה:</strong> אם בהזזת הפוקוסר הכוכב עובר מאליפסה אופקית לאליפסה אנכית, יש אסטיגמטיזם באופטיקה.</p>",
    "ASCOM (Astronomy Common Object Model)": "<p><strong>הגדרה:</strong> ASCOM הוא פרוטוקול תקשורת סטנדרטי ל-Windows המאפשר לתוכנות אסטרונומיה שונות (כמו N.I.N.A.) לתקשר עם חומרה שונה (כמו חצובת Losmandy G11).</p><p><strong>דוגמה:</strong> בהתקנת דרייבר ASCOM לחצובה שלך, כל תוכנה תואמת תוכל לשלוט בה מהמחשב ללא צורך באפליקציות קנייניות נפרדות.</p>",
    "INDI (Instrument Neutral Distributed Interface)": "<p><strong>הגדרה:</strong> INDI הוא המקביל ל-ASCOM עבור מערכת לינוקס, נפוץ בבקרים מבוססי Raspberry Pi כמו StellarMate או Astroberry.</p><p><strong>דוגמה:</strong> אם מפעילים את הציוד עם מחשב מיני בטלסקופ, INDI הוא כנראה שוטר התנועה שמנהל פקודות המצלמה והחצובה.</p>",
    "Sequencing": "<p><strong>הגדרה:</strong> תכנות רצף צילום הוא יצירת רשימת פקודות לביצוע אוטומטי (למשל: צלם 20 פריימי Red, אחר כך 20 פריימי Green, ואחר כך החנה את החצובה).</p><p><strong>דוגמה:</strong> ב-N.I.N.A. תוכל לבנות Sequence שממתין לעלייה של המטרה, מפקס כל שעה ושולח לך הודעה בסיום הסשן.</p>",
    "Guiding Rate": "<p><strong>הגדרה:</strong> קצב הנחיה הוא המהירות שבה החצובה נעה כשמקבלת תיקון מהמנחה האוטומטי, לרוב מבוטאת כשבר מקצב כוכבי (Sidereal) כגון 0.5x.</p><p><strong>דוגמה:</strong> אם ההנחיה מתנדנדת הלוך ושוב בצורה מהירה מדי, ייתכן שיש צורך להוריד את ה-Guiding Rate בהגדרות החצובה.</p>",
    "HFR (Half Flux Radius)": "<p><strong>הגדרה:</strong> HFR הוא מדד מתמטי המשמש תוכנת אוטו-פוקוס לקביעת חדות הכוכבים. הוא חזק יותר מ-FWHM לצורכי פיקוס.</p><p><strong>דוגמה:</strong> רוטינת האוטופוקוס תצלם מספר תמונות, תחשב HFR לכל אחת ותזיז את המנוע עד למציאת נקודת ה-V-curve שבה ה-HFR נמוך ביותר.</p>",
    "Bandpass (Full Width at Half Maximum - FWHM)": "<p><strong>הגדרה:</strong> Bandpass הוא רוחב החלון של אורכי הגל שהפילטר מאפשר לעבור. בפס צר נמדד בננומטרים (nm). FWHM מגדיר כמה רחב החלון הזה.</p><p><strong>דוגמה:</strong> פילטר Hα של 3nm חוסם הרבה יותר זיהום אור ואור ירח מאשר פילטר 7nm, ונותן ניגוד גבוה בהרבה לערפילית הטאדפול.</p>",
    "Filter Haloing": "<p><strong>הגדרה:</strong> הילת פילטר היא ארטיפקט השתקפות הנראה כרוח מעגלית סביב כוכבים בהירים, הנגרמת מהחזרת אור בין חיישן המצלמה לזכוכית הפילטר.</p><p><strong>דוגמה:</strong> בצילום הכוכב Alnitak באזור ערפילית ראש הסוס, פילטרי OIII זולים מציגים לרוב הילה כחולה גדולה שיש להסיר ידנית ב-PixInsight.</p>",
    "Signal Leakage (IR-Cut)": "<p><strong>הגדרה:</strong> דליפת אות IR מתרחשת כשפילטר או חיישן לא חוסם אור תת-אדום (IR), מה שגורם לכוכבים להיראות מנופחים כי אור IR מתכנס בנקודה אחרת מאור נראה.</p><p><strong>דוגמה:</strong> שימוש בפילטר L-Pro או UV/IR Cut מבטיח שרק הספקטרום הנראה מגיע לחיישן ושומר על כוכבים קטנים וחדים.</p>",
    "Transmission Percentage": "<p><strong>הגדרה:</strong> אחוז מעבר פילטר הוא אחוז האור הרצוי שעובר בהצלחה דרך הפילטר, כשהשאר נספג או מוחזר.</p><p><strong>דוגמה:</strong> פילטרים איכותיים (כמו Antlia או Chroma) מגיעים לאחוזי מעבר של 95-98%, כלומר כמעט ללא אובדן אות דרך הזכוכית.</p>",
    "Cable Snag / Cord Wrap": "<p><strong>הגדרה:</strong> פיתול כבלים הוא סכנה פיזית שבה הכבלים מסתבכים או נתפסים בחצובה בעת מעקב או הזזה של הטלסקופ.</p><p><strong>דוגמה:</strong> אם כבל ה-USB קצר מדי, Meridian Flip עלול לגרום לכבל למשוך את המצלמה ולפגוע בחיבור או לעצור את מנועי החצובה.</p>",
    "12V Power Distribution (Powerbox)": "<p><strong>הגדרה:</strong> Powerbox הוא רכזת חשמל מרכזית (כמו Pegasus Astro Pocket Powerbox) המקבלת כניסת חשמל אחת ומחלקת אותה למצלמה, לחצובה, למחממי טל ולמחשב מיני.</p><p><strong>דוגמה:</strong> במקום חמישה שנאי חשמל נפרדים, ה-Powerbox מאפשר להפעיל כבל טבור בודד לציוד, מה שמפחית גרירת כבלים.</p>",
    "Dew Point": "<p><strong>הגדרה:</strong> נקודת הטל היא הטמפרטורה שבה הלחות באוויר מתעבת למים נוזליים על פני שטח (כמו עדשת הטלסקופ). כשהעדשה מתקררת מתחת לנקודה זו, מצטבר טל.</p><p><strong>דוגמה:</strong> אם טמפרטורת עדשת הרפרקטור יורדת מתחת לנקודת הטל, התמונות יהיו ערפיליות. מחמם טל שומר על הזכוכית 1-2 מעלות מעל הטמפרטורה הסביבתית.</p>",
    "Histogram Stretching (Arsinh/Log)": "<p><strong>הגדרה:</strong> מתיחת היסטוגרמה היא הפונקציה המתמטית לחלוקה מחדש של ערכי פיקסל. מתיחת Arsinh פופולרית כי שומרת על הצבע הטבעי של הכוכבים תוך הארת ערפיליות עמומות.</p><p><strong>דוגמה:</strong> מתיחה לינארית רגילה תהפוך את הכוכבים ללבנים, ואילו ArsinhStretch שומרת על גוני כחול וכתום בזמן שמאירה את ערפילית אוריון.</p>",
    "Convolution vs. Deconvolution (Math)": "<p><strong>הגדרה:</strong> קונבולוציה היא פעולה מתמטית של טשטוש (ממוצע פיקסלים שכנים). דה-קונבולוציה היא פעולת ההפוך שמנסה למצוא את מקור האור המקורי.</p><p><strong>דוגמה:</strong> כשמשתמשים ב-Gaussian Blur, מבצעים קונבולוציה. כשמשתמשים ב-BlurXTerminator, מבצעים דה-קונבולוציה מורכבת לחידוד התמונה.</p>",
    "Noise Floor": "<p><strong>הגדרה:</strong> רצפת רעש היא רמת הרעש הרקע (רעש קריאה, רעש תרמי) שמתחתיה אי אפשר להבחין באותות אמיתיים מהאות.</p><p><strong>דוגמה:</strong> אם זרועות חיצוניות של גלקסיה מתחת לרצפת הרעש, אין כמות מתיחה שתראה אותן - פשוט נדרש יותר זמן אינטגרציה להרמת האות.</p>",
    "Bit Depth (14-bit vs 16-bit)": "<p><strong>הגדרה:</strong> עומק סיביות הוא מספר רמות האפור האפשריות שחיישן יכול לרשום. 16-bit מאפשר 65,536 רמות בהירות שונות, לעומת 4,096 ב-12-bit.</p><p><strong>דוגמה:</strong> ASI2600 (16-bit) מספק גרדיאנטים חלקים הרבה יותר בערפילית מאשר DSLR ישן של 12-bit, שעלול להראות פסים באזורים הכהים.</p>",
}

# Merge both dicts
translations = {}
translations.update(translations_part1)
translations.update(translations_part2)

print(f"Total translations loaded: {len(translations)}")

# Read the glossary file
with open(r'C:\Users\Savit\Documents\dsoimage-site\js\glossary_data.js', encoding='utf-8') as f:
    content = f.read()

# Check if already injected
if 'content_he:' in content:
    print("WARNING: content_he already found in file. Skipping to avoid double injection.")
else:
    def inject_content_he(match):
        full_match = match.group(0)
        title = match.group(1)
        he_content = translations.get(title)
        if he_content is None:
            print(f"WARNING: No translation for: {repr(title)}")
            return full_match
        # Insert content_he after the closing backtick of content
        he_field = f'\n        content_he: `{he_content}`'
        return full_match + he_field

    # Pattern: match title string then later content backtick block
    # Group 1 = the title string, group 0 = full block ending with content backtick
    pattern = re.compile(
        r'title: "([^"]+)"(?:(?!title:).)*?content: `[^`]*`',
        re.DOTALL
    )

    new_content, count = pattern.subn(inject_content_he, content)
    print(f"Matched and processed {count} items")

    with open(r'C:\Users\Savit\Documents\dsoimage-site\js\glossary_data.js', 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("File written successfully.")

# Verify
with open(r'C:\Users\Savit\Documents\dsoimage-site\js\glossary_data.js', encoding='utf-8') as f:
    result = f.read()
he_count = result.count('content_he:')
print(f"content_he entries in file: {he_count}")
